        if not os.path.exists(LOG_DIR):
            os.makedirs(LOG_DIR)
    except Exception as e:
        print(f"Failed to create log directory: {e}")
        exit(1)

def send_ntp_requests(target_ip, num_requests, interval, mode):
    """Sends NTP requests to the specified target IP."""
    ntp_data = b'\x1b' + 47 * b'\0'  # NTP request packet
    server_address = (target_ip, 123)  # NTP uses port 123

    for i in range(num_requests):
        try:
            if mode == 'live':
                with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                    sock.settimeout(5)  # Set a timeout for the socket
                    sock.sendto(ntp_data, server_address)
                    try:
                        response, _ = sock.recvfrom(512)  # Receive response
                        log_request(target_ip, 'Success', mode)
                    except socket.timeout:
                        log_request(target_ip, 'Timeout', mode)
            elif mode == 'offline':
                # Simulate success in offline mode
                log_request(target_ip, 'Simulated Success', mode)
        except Exception as e:
            log_request(target_ip, f'Failure: {e}', mode)
        time.sleep(interval)

def main():
    """Main function to execute the NTP requests."""
    # Default parameters
    target_ip = '127.0.0.1'  # Default IP address (localhost)
    num_requests = 10        # Default number of requests
    mode = 'offline'         # Default mode ('live' or 'offline')
    interval = 1.0           # Default interval in seconds

    ensure_log_directory()

    try:
        print(f"Sending {num_requests} NTP requests to {target_ip} in {mode} mode...")
        send_ntp_requests(target_ip, num_requests, interval, mode)
